def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Determine how many water units are likely available for a full requirement.
    # Use int() to avoid any float index issues (even though we don't index lists here).
    units = int(supply / float(WATER_REQ) + 1e-9)

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        # If no one else is alive, conserve budget.
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Use yesterday's bid pressure from opponents that were alive.
    prev_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev.get('bid')))

    # If we have no trace data, default to a conservative mid bid.
    if not prev_bids:
        base = DAILY_SALARY * 0.55
    else:
        highest_prev_bid = max(prev_bids)
        # If someone was bidding aggressively yesterday, match closer to avoid losing the auction.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base = DAILY_SALARY * (0.35 if my_status.get('hp', 0) > 3 else 0.95)
        else:
            # Otherwise, bid enough to beat low bidders but not overpay.
            base = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

    # Adjust for our own urgency.
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))
    budget = float(my_status.get('budget', 0.0))

    # If we're already low HP or have gone multiple days without water, push harder.
    if hp <= 2 or no_water_days >= 2:
        urgency_mult = 1.25
    elif hp <= 4 or no_water_days >= 1:
        urgency_mult = 1.10
    else:
        urgency_mult = 0.98

    # Supply-based adjustment: with tighter supply, we should be more competitive.
    if supply <= 18.0:
        supply_mult = 1.15
    elif supply <= 21.0:
        supply_mult = 1.05
    else:
        supply_mult = 0.95

    bid = base * urgency_mult * supply_mult

    # Hard caps: never exceed what we can pay, and avoid extreme overbidding.
    # Also, keep bids within a reasonable range relative to daily salary.
    bid = min(bid, budget)
    bid = min(bid, DAILY_SALARY * 1.75)

    # If our budget is tiny, still bid something to try to secure water.
    if bid < 1e-6:
        bid = min(budget, DAILY_SALARY * 0.25)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_current_budget, DAILY_SALARY * 0.1)

    david_alive = False
    david_yesterday_bid = 0.0
    other_opponents_max_bid = 0.0

    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                bid = prev_trace['bid']
                if opp_id == "David":
                    david_alive = True
                    david_yesterday_bid = bid
                else:
                    other_opponents_max_bid = max(other_opponents_max_bid, bid)

    base_bid = DAILY_SALARY * 0.5

    if my_current_hp <= 2 or my_no_water_days >= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_current_hp <= 5 or my_no_water_days >= 1:
        base_bid = DAILY_SALARY * 0.75

    if david_alive:
        if david_yesterday_bid > 0:
            if david_yesterday_bid >= DAILY_SALARY * 0.8:
                if my_current_hp <= 5 or my_no_water_days >= 1:
                    base_bid = max(base_bid, david_yesterday_bid + 5.0)
                else:
                    base_bid = max(base_bid, david_yesterday_bid * 0.9)
            elif david_yesterday_bid >= DAILY_SALARY * 0.5:
                base_bid = max(base_bid, david_yesterday_bid + 2.0)
            else:
                base_bid = max(base_bid, david_yesterday_bid + 1.0)

    if not david_alive or other_opponents_max_bid > david_yesterday_bid:
        if other_opponents_max_bid > 0:
            if other_opponents_max_bid >= DAILY_SALARY * 0.6 and (my_current_hp <= 5 or my_no_water_days >= 1):
                 base_bid = max(base_bid, other_opponents_max_bid + 2.0)
            else:
                base_bid = max(base_bid, other_opponents_max_bid + 0.5)

    final_bid = min(my_current_budget, base_bid)
    return max(0.1, final_bid)
